const [drawerCrewSearch, setDrawerCrewSearch] = useState('');

const [crewGroups, setCrewGroups] = useState<{ name: string; memberIds: string[] }[]>(() => {
  if (typeof window === 'undefined') return [];
  try {
    const saved = localStorage.getItem('7h_crew_groups');
    if (saved) return JSON.parse(saved);
  } catch {}
  const defaults = [
    { name: "Servers", memberIds: ['abbie', 'al', 'arjun', 'chris', 'emily'] },
    { name: "Kitchen", memberIds: ['andrea', 'dave_croke', 'dave_maas', 'emma'] },
    { name: "Managers", memberIds: ['daniel', 'david_xu', 'francesca'] }
  ];
  localStorage.setItem('7h_crew_groups', JSON.stringify(defaults));
  return defaults;
});
const [newGroupName, setNewGroupName] = useState('');
const [isSavingGroup, setIsSavingGroup] = useState(false);

const selectGroup = (group: { name: string; memberIds: string[] }) => {
  setSelectedCrewAssignments(() => {
    const next: { [crewId: string]: { active: boolean; customized?: boolean; role: string; startHour: number; endHour: number } } = {};
    group.memberIds.forEach(id => {
      next[id] = {
        active: true,
        customized: false,
        role: dropRole || 'SERVER',
        startHour: dropStartHour || 12,
        endHour: dropEndHour || 17
      };
    });
    return next;
  });
};

const deleteGroup = (name: string) => {
  setCrewGroups(prev => {
    const next = prev.filter(g => g.name !== name);
    localStorage.setItem('7h_crew_groups', JSON.stringify(next));
    return next;
  });
};

const handleSaveGroup = () => {
  const name = newGroupName.trim();
  if (!name) return;
  const activeIds = Object.entries(selectedCrewAssignments)
    .filter(([_, val]) => val.active)
    .map(([id]) => id);
  if (activeIds.length === 0) return;
  setCrewGroups(prev => {
    const updated = prev.filter(g => g.name.toLowerCase() !== name.toLowerCase());
    updated.push({ name, memberIds: activeIds });
    localStorage.setItem('7h_crew_groups', JSON.stringify(updated));
    return updated;
  });
  setNewGroupName('');
  setIsSavingGroup(false);
};
